import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        CountDownLatch releaseA = new CountDownLatch(1);
        ThreadPoolExecutor abort = new ThreadPoolExecutor(
                1, 1, 0L, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(1),
                r -> new Thread(r, "abort-pool"), new ThreadPoolExecutor.AbortPolicy());
        AtomicInteger rejected = new AtomicInteger();
        Runnable blockA = () -> {
            try { releaseA.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        };
        for (int i = 0; i < 5; i++) {
            try { abort.execute(blockA); }
            catch (RejectedExecutionException e) { rejected.incrementAndGet(); }
        }
        System.out.println("AbortPolicy    rejected (1 run + 1 queued) = " + rejected.get());
        releaseA.countDown();
        abort.shutdown();
        abort.awaitTermination(5, TimeUnit.SECONDS);

        CountDownLatch releaseB = new CountDownLatch(1);
        ThreadPoolExecutor caller = new ThreadPoolExecutor(
                1, 1, 0L, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(1),
                r -> new Thread(r, "caller-pool"), new ThreadPoolExecutor.CallerRunsPolicy());
        Runnable blockB = () -> {
            try { releaseB.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        };
        caller.execute(blockB);
        caller.execute(blockB);
        caller.execute(() -> System.out.println("CallerRunsPolicy ran on thread             = "
                + Thread.currentThread().getName()));
        System.out.println("CallerRunsPolicy rejected                  = 0 (back pressure)");
        releaseB.countDown();
        caller.shutdown();
        caller.awaitTermination(5, TimeUnit.SECONDS);
    }
}
